//! `dslvm`: the Rust runtime for lmscript `_dsl_` bytecode (format v5), the second runtime after the C++ reference
//! (`lmctlhq/cpp-dsl-sdk/include/dslvm.hpp`). Same semantics, same error classes; the shared contract is the conformance
//! vector set generated by the lmscript compiler. No external crates. Living spec: lmctl-mono
//! `lmscript/durable-memory/design/dsl-language.md`; team guide `lmscript/durable-memory/dsl-framework.md`.
//!
//! Embedding (see README for the full example): build a [`Registry`] that implements the schema (`context`, `method`,
//! `function`), [`Program::load`] the bytecode with the exact schema bytes (refused before anything runs on any problem),
//! then per event create a [`Context`], insert the host objects, and [`Program::run`].
//!
//! Host-object ownership: a [`Context`] owns every object of one run (`Box<dyn Any>` in an arena); the DSL only ever sees
//! an [`ObjRef`] (index + schema type name). Methods receive `&mut Context` and borrow their object through
//! `ctx.get_mut::<T>(obj)`, so there is exactly one mutable path and no `Rc<RefCell<_>>` is needed; the host takes its
//! objects back with `ctx.take::<T>(obj)` after the run or lets the context drop them. Handles are valid for one run only,
//! which is what the language promises (R12: the host owns lifetime; the DSL cannot store or return handles).

pub mod sha256;
pub use sha256::{hex, sha256};

use std::any::Any;
use std::collections::HashMap;
use std::fmt;

/// The bytecode format version this runtime reads. Every other version (v4 included) is refused: no backward compatibility.
///
/// Format v5 (big-endian, fixed widths; spec v5): `DSLB`, u16 version, sha256(schema bytes); constants (u32 count, each
/// u8 tag 1 + u32 length + UTF-8); imports (u16 count, each u32 constant index of a canonical signature `fn NAME(T) -> R` or
/// `method Type.name(T) -> R`, resolved against the registry at load); context (u16 count, each u32 name + u32 type constant,
/// checked against the registry); locals (u16 count, each u32 type-name constant + u8 hidden flag); u16 max_stack (the
/// compiler's measured depth, a reservation hint); code (u32 length, ends with HALT); lines (u32 count, each u32 pc + u32
/// line + u16 column, may be empty). Ints are 64-bit two's complement with wraparound (no overflow trap, R34); division and
/// remainder by zero are run-time errors. The language and the VM impose no memory or time limits (operator decision
/// 2026-10-18): no stack cap, no locals cap, no string cap.
pub const VERSION: u16 = 5;
const MAGIC: &[u8; 4] = b"DSLB";

/// Load, verify and run-time failures: a message naming the problem and a code (`LOAD_BAD_BYTECODE`, `LOAD_SCHEMA_MISMATCH`,
/// `LOAD_UNBOUND`, `RUN_ERROR` for a VM error, `RUN_HOST` for an error a host closure returned, `APP_FAIL` for the host's own
/// application failure). `Error::host(msg)` is what host closures return. Exit-code convention (spec v4 D7, R26): 2 compile
/// (lmscript), 3 load or run, 4 application; see [`report_error`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error { pub code: String, pub message: String }
impl Error {
    pub fn new(code: &str, message: impl Into<String>) -> Error { Error { code: code.to_string(), message: message.into() } }
    pub fn host(message: impl Into<String>) -> Error { Error::new("RUN_HOST", message) }
}
impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { f.write_str(&self.message) }
}
impl std::error::Error for Error {}
fn err<T>(message: impl Into<String>) -> Result<T, Error> { Err(Error::new("RUN_ERROR", message)) }
fn load_err<T>(code: &str, message: impl Into<String>) -> Result<T, Error> { Err(Error::new(code, message)) }

/// JSON string literal for the result line.
pub fn json_escape(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() { match c { '"' => out.push_str("\\\""), '\\' => out.push_str("\\\\"), '\n' => out.push_str("\\n"), '\r' => out.push_str("\\r"), '\t' => out.push_str("\\t"), c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)), c => out.push(c) } }
    out.push('"'); out
}
/// The standard result line (spec v4 D7, R26): exactly one JSON line on stdout. `result_json` is JSON text already.
pub fn report_ok(result_json: &str) -> i32 { println!("{{\"ok\": true, \"result\": {}}}", result_json); 0 }
/// phase is "load" or "run" (compile failures are lmscript's, exit 2); returns the exit code: 4 for APP_FAIL, else 3.
pub fn report_error(phase: &str, e: &Error) -> i32 {
    println!("{{\"ok\": false, \"phase\": {}, \"code\": {}, \"message\": {}}}", json_escape(phase), json_escape(&e.code), json_escape(&e.message));
    if e.code == "APP_FAIL" { 4 } else { 3 }
}
pub fn report_app_failure(message: &str) -> i32 { report_error("app", &Error::new("APP_FAIL", message)) }

/// A handle to a host object living in a [`Context`] for one run.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct ObjRef(usize);

/// A DSL value. `Obj` carries the schema type name the compiler saw; the VM checks it on every method call.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    None,
    Int(i64),
    Float(f64),
    Str(String),
    Bool(bool),
    Obj { type_name: String, obj: ObjRef },
}
impl Value {
    pub fn kind_name(&self) -> &'static str {
        match self { Value::None => "void", Value::Int(_) => "int", Value::Float(_) => "float", Value::Str(_) => "string", Value::Bool(_) => "bool", Value::Obj { .. } => "object" }
    }
    pub fn object(type_name: impl Into<String>, obj: ObjRef) -> Value { Value::Obj { type_name: type_name.into(), obj } }
    /// Accessors for host callbacks: the VM guarantees the kinds the schema declares, so a mismatch is a host or compiler bug.
    pub fn as_int(&self) -> Result<i64, Error> { if let Value::Int(i) = self { Ok(*i) } else { err(format!("expected int, got {}", self.kind_name())) } }
    pub fn as_float(&self) -> Result<f64, Error> { if let Value::Float(f) = self { Ok(*f) } else { err(format!("expected float, got {}", self.kind_name())) } }
    pub fn as_str(&self) -> Result<&str, Error> { if let Value::Str(s) = self { Ok(s) } else { err(format!("expected string, got {}", self.kind_name())) } }
    pub fn as_bool(&self) -> Result<bool, Error> { if let Value::Bool(b) = self { Ok(*b) } else { err(format!("expected bool, got {}", self.kind_name())) } }
    pub fn as_obj(&self) -> Result<ObjRef, Error> { if let Value::Obj { obj, .. } = self { Ok(*obj) } else { err(format!("expected object, got {}", self.kind_name())) } }
}

/// The live objects of one run: an arena the host fills before `run` and empties (or drops) after it.
#[derive(Default)]
pub struct Context {
    objects: Vec<Option<Box<dyn Any>>>,
    types: Vec<String>,
    names: HashMap<String, ObjRef>,
}
impl Context {
    pub fn new() -> Context { Context::default() }
    /// Stores a host object under its schema type name and returns the handle.
    pub fn insert<T: Any>(&mut self, type_name: impl Into<String>, object: T) -> ObjRef {
        self.objects.push(Some(Box::new(object)));
        self.types.push(type_name.into());
        ObjRef(self.objects.len() - 1)
    }
    /// Binds a context variable (declared in the registry) to an object for this run.
    pub fn set(&mut self, name: impl Into<String>, obj: ObjRef) { self.names.insert(name.into(), obj); }
    /// Inserts and binds in one step.
    pub fn set_object<T: Any>(&mut self, name: impl Into<String>, type_name: impl Into<String>, object: T) -> ObjRef {
        let r = self.insert(type_name, object); self.set(name, r); r
    }
    pub fn type_name(&self, obj: ObjRef) -> &str { &self.types[obj.0] }
    pub fn get<T: Any>(&self, obj: ObjRef) -> Result<&T, Error> {
        self.objects.get(obj.0).and_then(|o| o.as_ref()).and_then(|b| b.downcast_ref::<T>()).ok_or_else(|| Error::host(format!("context object #{} is not a {}", obj.0, std::any::type_name::<T>())))
    }
    pub fn get_mut<T: Any>(&mut self, obj: ObjRef) -> Result<&mut T, Error> {
        self.objects.get_mut(obj.0).and_then(|o| o.as_mut()).and_then(|b| b.downcast_mut::<T>()).ok_or_else(|| Error::host(format!("context object #{} is not a {}", obj.0, std::any::type_name::<T>())))
    }
    /// Takes an object back out of the arena (the handle becomes invalid).
    pub fn take<T: Any>(&mut self, obj: ObjRef) -> Result<T, Error> {
        let slot = self.objects.get_mut(obj.0).ok_or_else(|| Error::host(format!("no context object #{}", obj.0)))?;
        match slot.take() { Some(b) => b.downcast::<T>().map(|b| *b).map_err(|_| Error::host(format!("context object #{} is not a {}", obj.0, std::any::type_name::<T>()))), None => Err(Error::host(format!("context object #{} was already taken", obj.0))) }
    }
    pub fn lookup(&self, name: &str) -> Option<ObjRef> { self.names.get(name).copied() }
    pub fn len(&self) -> usize { self.objects.len() }
    pub fn is_empty(&self) -> bool { self.objects.is_empty() }
}

pub type Args = [Value];
/// A host function: receives the run's context (to create objects or reach host state) and the arguments in order.
pub type Function = Box<dyn Fn(&mut Context, &Args) -> Result<Value, Error>>;
/// A host method: the receiver handle, the context (borrow the object with `ctx.get_mut::<T>(this)`) and the arguments.
pub type Method = Box<dyn Fn(&mut Context, ObjRef, &Args) -> Result<Value, Error>>;

/// A declared signature: the schema's parameter type names and return type name (`void` for none).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Signature { pub params: Vec<String>, pub returns: String }
impl Signature { fn text(&self) -> String { format!("({}) -> {}", self.params.join(", "), self.returns) } }

/// The implementation of the schema the bytecode was compiled against, declared with the schema's types. The loader binds
/// by its complete canonical signature; distinct parameter tuples under one name are overloads. `signatures()` lists the canonical
/// strings `lmscript --dsl-signatures SCHEMA` prints so a host test can diff the two sources of truth (spec v4 S0, A02). Per
/// R33/R34 the VM performs no call-time checks. Registering a parameter tuple twice is an error (`LOAD_UNBOUND`).
#[derive(Default)]
pub struct Registry {
    // Keys include the complete canonical signature. This permits overloads while keeping
    // import binding exact and deterministic; a duplicate parameter tuple is rejected below.
    functions: HashMap<String, (String, Signature, Function)>,
    methods: HashMap<String, (String, String, Signature, Method)>,
    contexts: HashMap<String, String>,
}
impl Registry {
    pub fn new() -> Registry { Registry::default() }
    pub fn function(&mut self, name: &str, params: &[&str], returns: &str, f: impl Fn(&mut Context, &Args) -> Result<Value, Error> + 'static) -> Result<&mut Self, Error> {
        let sig = Signature { params: params.iter().map(|p| p.to_string()).collect(), returns: returns.to_string() };
        if self.functions.values().any(|(n, old, _f)| n == name && old.params == sig.params) { return load_err("LOAD_UNBOUND", format!("registry: function '{}{}' is registered twice", name, sig.text())); }
        let canonical = format!("fn {}{}", name, sig.text());
        self.functions.insert(canonical, (name.to_string(), sig, Box::new(f)));
        Ok(self)
    }
    pub fn method(&mut self, type_name: &str, name: &str, params: &[&str], returns: &str, f: impl Fn(&mut Context, ObjRef, &Args) -> Result<Value, Error> + 'static) -> Result<&mut Self, Error> {
        let sig = Signature { params: params.iter().map(|p| p.to_string()).collect(), returns: returns.to_string() };
        if self.methods.values().any(|(t, n, old, _f)| t == type_name && n == name && old.params == sig.params) { return load_err("LOAD_UNBOUND", format!("registry: method '{}.{}{}' is registered twice", type_name, name, sig.text())); }
        let canonical = format!("method {}.{}{}", type_name, name, sig.text());
        self.methods.insert(canonical, (type_name.to_string(), name.to_string(), sig, Box::new(f)));
        Ok(self)
    }
    /// Declares a context variable and its schema type; `Context::set` provides the object per run.
    pub fn context(&mut self, name: &str, type_name: &str) -> Result<&mut Self, Error> {
        if self.contexts.insert(name.to_string(), type_name.to_string()).is_some() { return load_err("LOAD_UNBOUND", format!("registry: context '{}' is declared twice", name)); }
        Ok(self)
    }
    pub fn context_type(&self, name: &str) -> Option<&str> { self.contexts.get(name).map(String::as_str) }
    fn function_by_signature(&self, canonical: &str) -> Option<&(String, Signature, Function)> { self.functions.get(canonical) }
    fn method_by_signature(&self, canonical: &str) -> Option<&(String, String, Signature, Method)> { self.methods.get(canonical) }
    /// "fn x(float) -> int" as the host declares the name an import asks for, or "" when the name is unknown.
    fn declared_for(&self, canonical: &str) -> String {
        let (Some(sp), Some(par)) = (canonical.find(' '), canonical.find('(')) else { return String::new() };
        if par < sp { return String::new(); }
        let name = &canonical[sp + 1..par];
        if let Some(_rest) = canonical.strip_prefix("fn ") {
            let mut have: Vec<String> = self.functions.values().filter(|(n, _s, _f)| n == name).map(|(_, s, _)| format!("fn {}{}", name, s.text())).collect();
            have.sort(); return have.join(", ");
        }
        let Some((t, n)) = name.split_once('.') else { return String::new() };
        let mut have: Vec<String> = self.methods.values().filter(|(ty, method, _s, _f)| ty == t && method == n).map(|(_, _, s, _)| format!("method {}{}", name, s.text())).collect();
        have.sort(); have.join(", ")
    }
    /// Sorted canonical strings: `context NAME: Type`, `fn NAME(T, ...) -> R`, `method Type.name(T, ...) -> R`.
    pub fn signatures(&self) -> Vec<String> {
        let mut out: Vec<String> = self.contexts.iter().map(|(n, t)| format!("context {}: {}", n, t)).collect();
        out.extend(self.functions.keys().cloned());
        out.extend(self.methods.keys().cloned());
        out.sort(); out
    }
}

#[allow(non_camel_case_types, clippy::upper_case_acronyms)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[repr(u8)]
enum Op {
    PUSH_INT = 0x01, PUSH_STR = 0x02, PUSH_BOOL = 0x03, LOAD_LOCAL = 0x04, STORE_LOCAL = 0x05, LOAD_CTX = 0x06, CALL_FN = 0x07, CALL_METHOD = 0x08,
    EQ = 0x09, NE = 0x0A, NOT = 0x0B, JUMP = 0x0C, JUMP_IF_FALSE = 0x0D, JUMP_IF_TRUE = 0x0E, DUP = 0x0F, POP = 0x10, HALT = 0x11,
    PUSH_FLOAT = 0x12, ADD_I = 0x13, SUB_I = 0x14, MUL_I = 0x15, DIV_I = 0x16, ADD_F = 0x17, SUB_F = 0x18, MUL_F = 0x19, DIV_F = 0x1A, NEG_I = 0x1B, NEG_F = 0x1C,
    LT_I = 0x1D, LE_I = 0x1E, GT_I = 0x1F, GE_I = 0x20, LT_F = 0x21, LE_F = 0x22, GT_F = 0x23, GE_F = 0x24, I2F = 0x25, CONCAT = 0x26, I2S = 0x27, F2S = 0x28, B2S = 0x29,
    MATH = 0x32, MOD_I = 0x33, FOR_RANGE = 0x2F, FOR_NEXT = 0x31, WHILE_BEGIN = 0x34, WHILE_TEST = 0x35, LOOP_BACK = 0x36,
}
impl Op {
    fn decode(b: u8) -> Option<Op> {
        use Op::*;
        const ALL: [Op; 48] = [PUSH_INT, PUSH_STR, PUSH_BOOL, LOAD_LOCAL, STORE_LOCAL, LOAD_CTX, CALL_FN, CALL_METHOD, EQ, NE, NOT, JUMP, JUMP_IF_FALSE, JUMP_IF_TRUE, DUP, POP, HALT,
            PUSH_FLOAT, ADD_I, SUB_I, MUL_I, DIV_I, ADD_F, SUB_F, MUL_F, DIV_F, NEG_I, NEG_F, LT_I, LE_I, GT_I, GE_I, LT_F, LE_F, GT_F, GE_F, I2F, CONCAT, I2S, F2S, B2S, MATH, MOD_I, FOR_RANGE, FOR_NEXT, WHILE_BEGIN, WHILE_TEST, LOOP_BACK];
        ALL.iter().copied().find(|op| *op as u8 == b)
    }
}

struct Reader<'a> { b: &'a [u8], pos: usize }
impl<'a> Reader<'a> {
    fn new(b: &'a [u8]) -> Reader<'a> { Reader { b, pos: 0 } }
    fn need(&self, n: usize) -> Result<(), Error> {
        if self.pos + n > self.b.len() { return load_err("LOAD_BAD_BYTECODE", format!("bytecode is truncated: wanted {} byte(s) at offset {}, file has {}", n, self.pos, self.b.len())); }
        Ok(())
    }
    fn u8(&mut self) -> Result<u8, Error> { self.need(1)?; let v = self.b[self.pos]; self.pos += 1; Ok(v) }
    fn u16(&mut self) -> Result<u16, Error> { self.need(2)?; let v = u16::from_be_bytes([self.b[self.pos], self.b[self.pos + 1]]); self.pos += 2; Ok(v) }
    fn u32(&mut self) -> Result<u32, Error> { self.need(4)?; let v = u32::from_be_bytes(self.b[self.pos..self.pos + 4].try_into().unwrap()); self.pos += 4; Ok(v) }
    fn i32(&mut self) -> Result<i32, Error> { Ok(self.u32()? as i32) }
    fn i64(&mut self) -> Result<i64, Error> { self.need(8)?; let v = i64::from_be_bytes(self.b[self.pos..self.pos + 8].try_into().unwrap()); self.pos += 8; Ok(v) }
    fn f64(&mut self) -> Result<f64, Error> { self.need(8)?; let v = f64::from_be_bytes(self.b[self.pos..self.pos + 8].try_into().unwrap()); self.pos += 8; Ok(v) }
    fn bytes(&mut self, n: usize) -> Result<&'a [u8], Error> { self.need(n)?; let s = &self.b[self.pos..self.pos + n]; self.pos += n; Ok(s) }
    fn done(&self) -> bool { self.pos == self.b.len() }
}

/// One resolved import: the host entry a `CALL_FN`/`CALL_METHOD` names (an index into the registry's maps by canonical string).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Import { Function(String), Method(String, String, String) }
/// A declared local slot: its type name and whether the compiler hid it (loop machinery, never a user variable).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Local { pub type_name: String, pub hidden: bool }
/// One line-table entry: the source position of the instruction at `pc` and every following one up to the next entry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Line { pub pc: u32, pub line: u32, pub column: u16 }

/// A loaded, verified program. Immutable; run it as often as the host likes.
#[derive(Debug, Clone)]
pub struct Program { consts: Vec<String>, imports: Vec<Import>, contexts: Vec<String>, locals: Vec<Local>, max_stack: u16, code: Vec<u8>, lines: Vec<Line>, loop_pairs: HashMap<usize, (usize, usize)> }

impl Program {
    /// Parses, binds against the registry and verifies. Nothing executes here; every problem is an `Err`.
    pub fn load(bytecode: &[u8], schema_bytes: &[u8], reg: &Registry) -> Result<Program, Error> {
        if bytecode.len() < 4 || &bytecode[..4] != MAGIC { return load_err("LOAD_BAD_BYTECODE", "not a DSL bytecode file: bad magic (expected 'DSLB')"); }
        let mut r = Reader::new(bytecode);
        r.bytes(4)?;
        let version = r.u16()?;
        if version != VERSION { return load_err("LOAD_BAD_BYTECODE", format!("unsupported bytecode version {} (this runtime reads version {})", version, VERSION)); }
        let hash = r.bytes(32)?;
        let expected = sha256(schema_bytes);
        if hash != expected { return load_err("LOAD_SCHEMA_MISMATCH", format!("schema mismatch: bytecode was compiled against schema sha256 {}, the given schema has sha256 {}", hex(hash), hex(&expected))); }
        let nconst = r.u32()?;
        let mut consts: Vec<String> = Vec::with_capacity(nconst as usize);
        for i in 0..nconst {
            let tag = r.u8()?;
            if tag != 1 { return load_err("LOAD_BAD_BYTECODE", format!("constant {} has unknown tag {} (1 = string)", i, tag)); }
            let len = r.u32()? as usize;
            let raw = r.bytes(len)?;
            consts.push(String::from_utf8(raw.to_vec()).map_err(|_| Error::new("LOAD_BAD_BYTECODE", format!("constant {} is not valid UTF-8", i)))?);
        }
        let cidx = |i: u32, what: &str| -> Result<&str, Error> { consts.get(i as usize).map(String::as_str).ok_or_else(|| Error::new("LOAD_BAD_BYTECODE", format!("{}: constant index {} out of range ({} constants)", what, i, consts.len()))) };
        let nimports = r.u16()?;
        let mut imports = Vec::with_capacity(nimports as usize);
        for _ in 0..nimports {
            let canonical = cidx(r.u32()?, "import")?;
            let resolved = if canonical.starts_with("fn ") {
                reg.function_by_signature(canonical).map(|_| Import::Function(canonical.to_string()))
            } else if let Some(rest) = canonical.strip_prefix("method ") {
                let head = &rest[..rest.find('(').unwrap_or(rest.len())];
                match (reg.method_by_signature(canonical), head.split_once('.')) { (Some(_), Some((t, n))) => Some(Import::Method(canonical.to_string(), t.to_string(), n.to_string())), _ => None }
            } else { None };
            match resolved {
                Some(imp) => imports.push(imp),
                None => { let have = reg.declared_for(canonical); return load_err("LOAD_UNBOUND", format!("import '{}' is not provided by the host{}", canonical, if have.is_empty() { String::new() } else { format!(" (the host declares {})", have) })); }
            }
        }
        let ncontext = r.u16()?;
        let mut contexts = Vec::with_capacity(ncontext as usize);
        for _ in 0..ncontext {
            let name = cidx(r.u32()?, "context name")?; let type_name = cidx(r.u32()?, "context type")?;
            match reg.context_type(name) {
                None => return load_err("LOAD_UNBOUND", format!("context variable '{}' is not declared by the host", name)),
                Some(t) if t != type_name => return load_err("LOAD_UNBOUND", format!("context variable '{}' is declared as {} by the bytecode, the host provides {}", name, type_name, t)),
                Some(_) => contexts.push(name.to_string()),
            }
        }
        let nlocals = r.u16()?;
        let mut locals = Vec::with_capacity(nlocals as usize);
        for i in 0..nlocals {
            let type_name = cidx(r.u32()?, "local type")?.to_string(); let hidden = r.u8()?;
            if hidden > 1 { return load_err("LOAD_BAD_BYTECODE", format!("local {} hidden flag must be 0 or 1", i)); }
            locals.push(Local { type_name, hidden: hidden == 1 });
        }
        let max_stack = r.u16()?;
        let code_len = r.u32()? as usize;
        let code = r.bytes(code_len)?.to_vec();
        let nlines = r.u32()?;
        let mut lines: Vec<Line> = Vec::with_capacity(nlines as usize);
        for i in 0..nlines {
            let l = Line { pc: r.u32()?, line: r.u32()?, column: r.u16()? };
            if let Some(prev) = lines.last() { if l.pc < prev.pc { return load_err("LOAD_BAD_BYTECODE", format!("line table is not sorted by pc at entry {}", i)); } }
            lines.push(l);
        }
        if !r.done() { return load_err("LOAD_BAD_BYTECODE", format!("bytecode has {} trailing byte(s) after the line table", bytecode.len() - r.pos)); }
        let mut p = Program { consts, imports, contexts, locals, max_stack, code, lines, loop_pairs: HashMap::new() };
        p.loop_pairs = p.verify(reg)?;
        p.verify_stack(reg)?;
        Ok(p)
    }

    pub fn constant_count(&self) -> usize { self.consts.len() }
    pub fn code_size(&self) -> usize { self.code.len() }
    pub fn import_count(&self) -> usize { self.imports.len() }
    pub fn locals(&self) -> &[Local] { &self.locals }
    pub fn max_stack(&self) -> u16 { self.max_stack }
    pub fn lines(&self) -> &[Line] { &self.lines }
    /// The source position recorded for a pc (the last line-table entry at or before it); `None` when the table has none.
    pub fn line_of(&self, pc: usize) -> Option<Line> { self.lines.iter().take_while(|l| l.pc as usize <= pc).last().copied() }

    fn import_sig<'a>(&self, reg: &'a Registry, i: usize) -> Option<&'a Signature> {
        match &self.imports[i] { Import::Function(canonical) => reg.functions.get(canonical).map(|(_, s, _)| s), Import::Method(canonical, _, _) => reg.methods.get(canonical).map(|(_, _, s, _)| s) }
    }

    /// Static verification: every instruction decodes, every index is in range, and ordinary jumps land on instruction
    /// starts in the same lexical region.  Range loops are the one structured backward edge: their FOR_NEXT must pair
    /// with the innermost FOR_RANGE, return to its body start, and use distinct compiler-owned integer locals.  This is
    /// deliberately structural; there is no iteration counter or other run-time termination check (R25/R34).
    fn verify(&self, reg: &Registry) -> Result<HashMap<usize, (usize, usize)>, Error> {
        let mut r = Reader::new(&self.code);
        let mut starts: Vec<usize> = Vec::new();
        #[derive(Clone, Copy)]
        struct LoopFrame { opener: usize, body: usize, counter: usize, end: usize, exit: usize, op: Op, parent: Option<usize>, tested: bool }
        #[derive(Clone, Copy)]
        struct Jump { at: usize, target: usize, ordinary: bool }
        let mut jumps: Vec<Jump> = Vec::new();
        let mut loops: Vec<LoopFrame> = Vec::new();
        let mut all_loops: Vec<LoopFrame> = Vec::new();
        let mut while_exits: Vec<(usize, usize)> = Vec::new();
        let mut loop_pairs: HashMap<usize, (usize, usize)> = HashMap::new();
        let mut loop_slots: Vec<usize> = Vec::new();
        let mut halted = false;
        let index = |i: usize, n: usize, what: &str| -> Result<(), Error> { if i >= n { load_err("LOAD_BAD_BYTECODE", format!("{} index {} out of range ({} entries)", what, i, n)) } else { Ok(()) } };
        while !r.done() {
            let at = r.pos; starts.push(at);
            let byte = r.u8()?;
            let op = Op::decode(byte).ok_or_else(|| Error::new("LOAD_BAD_BYTECODE", format!("unknown opcode {} at offset {}", byte, at)))?;
            halted = false;
            use Op::*;
            match op {
                PUSH_INT => { r.i64()?; }
                PUSH_FLOAT => { r.f64()?; }
                PUSH_STR => { index(r.u32()? as usize, self.consts.len(), "constant")?; }
                PUSH_BOOL => { let v = r.u8()?; if v > 1 { return load_err("LOAD_BAD_BYTECODE", "PUSH_BOOL operand must be 0 or 1"); } }
                LOAD_LOCAL | STORE_LOCAL => {
                    let slot = r.u16()? as usize;
                    index(slot, self.locals.len(), "local slot")?;
                    if op == STORE_LOCAL && self.locals[slot].hidden {
                        return load_err("LOAD_BAD_BYTECODE", format!("STORE_LOCAL at offset {} writes compiler-owned loop local {}", at, slot));
                    }
                }
                LOAD_CTX => { index(r.u16()? as usize, self.contexts.len(), "context")?; }
                CALL_FN | CALL_METHOD => {
                    let i = r.u16()? as usize; let argc = r.u8()? as usize; index(i, self.imports.len(), "import")?;
                    let name = if op == CALL_FN { "CALL_FN" } else { "CALL_METHOD" };
                    match (&self.imports[i], op) {
                        (Import::Method(..), CALL_FN) => return load_err("LOAD_BAD_BYTECODE", format!("CALL_FN at offset {} names import {}, which is a method", at, i)),
                        (Import::Function(_), CALL_METHOD) => return load_err("LOAD_BAD_BYTECODE", format!("CALL_METHOD at offset {} names import {}, which is a function", at, i)),
                        _ => {}
                    }
                    let sig = self.import_sig(reg, i).ok_or_else(|| Error::new("LOAD_UNBOUND", format!("import {} vanished from the registry", i)))?;
                    if sig.params.len() != argc { return load_err("LOAD_BAD_BYTECODE", format!("{} at offset {} passes {} argument(s), the import takes {}", name, at, argc, sig.params.len())); }
                }
                MATH => {
                    let fn_id = r.u8()?;
                    if !matches!(fn_id, 0..=17) { return load_err("LOAD_BAD_BYTECODE", format!("MATH at offset {} has unknown function {}", at, fn_id)); }
                }
                EQ | NE | NOT | DUP | POP | ADD_I | SUB_I | MUL_I | DIV_I | MOD_I | ADD_F | SUB_F | MUL_F | DIV_F | NEG_I | NEG_F | LT_I | LE_I | GT_I | GE_I | LT_F | LE_F | GT_F | GE_F | I2F | CONCAT | I2S | F2S | B2S => {}
                JUMP | JUMP_IF_FALSE | JUMP_IF_TRUE => {
                    let rel = r.i32()?;
                    if rel < 0 { return load_err("LOAD_BAD_BYTECODE", format!("jump at offset {} goes backwards outside a range loop", at)); }
                    let target = r.pos as i64 + rel as i64;
                    if target < 0 { return load_err("LOAD_BAD_BYTECODE", format!("jump at offset {} has an invalid target", at)); }
                    jumps.push(Jump { at, target: target as usize, ordinary: true });
                }
                FOR_RANGE => {
                    let counter = r.u16()? as usize;
                    let end = r.u16()? as usize;
                    let rel = r.i32()?;
                    index(counter, self.locals.len(), "FOR_RANGE counter local")?;
                    index(end, self.locals.len(), "FOR_RANGE end local")?;
                    if counter == end { return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} reuses local {} for counter and end", at, counter)); }
                    for slot in [counter, end] {
                        if !self.locals[slot].hidden || self.locals[slot].type_name != "int" {
                            return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} requires hidden int local {}, got {}{}", at, slot, if self.locals[slot].hidden { "" } else { "visible " }, self.locals[slot].type_name));
                        }
                        if loop_slots.contains(&slot) { return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} reuses loop local {}", at, slot)); }
                        loop_slots.push(slot);
                    }
                    let target = r.pos as i64 + rel as i64;
                    if target < 0 { return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} has an invalid exit target", at)); }
                    let exit = target as usize;
                    if exit <= at { return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} exits backwards", at)); }
                    let frame = LoopFrame { opener: at, body: r.pos, counter, end, exit, op: FOR_RANGE, parent: loops.last().map(|f| f.opener), tested: false };
                    loops.push(frame);
                    all_loops.push(frame);
                }
                FOR_NEXT => {
                    let end = r.u16()? as usize;
                    let rel = r.i32()?;
                    let Some(frame) = loops.pop() else { return load_err("LOAD_BAD_BYTECODE", format!("FOR_NEXT at offset {} has no matching FOR_RANGE", at)); };
                    if end != frame.end { return load_err("LOAD_BAD_BYTECODE", format!("FOR_NEXT at offset {} closes the wrong range loop (end local {}, expected {})", at, end, frame.end)); }
                    let target = r.pos as i64 + rel as i64;
                    if target != frame.body as i64 { return load_err("LOAD_BAD_BYTECODE", format!("FOR_NEXT at offset {} must jump to its FOR_RANGE body start {}", at, frame.body)); }
                    if rel >= 0 { return load_err("LOAD_BAD_BYTECODE", format!("FOR_NEXT at offset {} must jump backwards", at)); }
                    jumps.push(Jump { at, target: frame.body, ordinary: false });
                    loop_pairs.insert(at, (frame.counter, frame.end));
                    // The FOR_RANGE exit is the only legal edge out of this loop. It must land after the matching NEXT.
                    if frame.exit != r.pos { return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} must exit immediately after its FOR_NEXT", frame.opener)); }
                }
                WHILE_BEGIN => {
                    let frame = LoopFrame { opener: at, body: r.pos, counter: 0, end: 0, exit: 0, op: WHILE_BEGIN, parent: loops.last().map(|f| f.opener), tested: false };
                    loops.push(frame);
                }
                WHILE_TEST => {
                    let rel = r.i32()?;
                    let Some(frame) = loops.last_mut() else { return load_err("LOAD_BAD_BYTECODE", format!("WHILE_TEST at offset {} has no matching WHILE_BEGIN", at)); };
                    if frame.op != WHILE_BEGIN { return load_err("LOAD_BAD_BYTECODE", format!("WHILE_TEST at offset {} has no matching WHILE_BEGIN", at)); }
                    if frame.tested { return load_err("LOAD_BAD_BYTECODE", format!("WHILE_BEGIN at offset {} has more than one WHILE_TEST", frame.opener)); }
                    if rel < 0 { return load_err("LOAD_BAD_BYTECODE", format!("WHILE_TEST at offset {} exits backwards", at)); }
                    frame.tested = true; frame.exit = (r.pos as i64 + rel as i64) as usize; while_exits.push((at, frame.exit));
                }
                LOOP_BACK => {
                    let rel = r.i32()?;
                    let Some(frame) = loops.pop() else { return load_err("LOAD_BAD_BYTECODE", format!("LOOP_BACK at offset {} has no matching WHILE_BEGIN", at)); };
                    if frame.op != WHILE_BEGIN || !frame.tested { return load_err("LOAD_BAD_BYTECODE", format!("LOOP_BACK at offset {} has no matching tested WHILE_BEGIN", at)); }
                    if r.pos as i64 + rel as i64 != frame.opener as i64 { return load_err("LOAD_BAD_BYTECODE", format!("LOOP_BACK at offset {} does not target its paired WHILE_BEGIN", at)); }
                    if frame.exit != r.pos { return load_err("LOAD_BAD_BYTECODE", format!("WHILE_TEST at offset {} must exit immediately after its LOOP_BACK", frame.opener)); }
                    all_loops.push(LoopFrame { exit: frame.exit, ..frame });
                }
                HALT => {
                    if !loops.is_empty() { return load_err("LOAD_BAD_BYTECODE", format!("HALT at offset {} is inside loop", at)); }
                    halted = true;
                }
            }
        }
        if !halted { return load_err("LOAD_BAD_BYTECODE", "code does not end with HALT"); }
        if let Some(frame) = loops.last() { return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} is not closed by FOR_NEXT", frame.opener)); }
        for jump in jumps {
            if !starts.contains(&jump.target) { return load_err("LOAD_BAD_BYTECODE", format!("jump at offset {} targets {}, not an instruction start", jump.at, jump.target)); }
            if jump.ordinary {
                // Ordinary jumps may not cross a structured loop boundary. The compiler uses FOR_RANGE's exit edge
                // to leave a loop, and FOR_NEXT's paired edge to re-enter one.
                let region = |pc: usize| -> Option<usize> {
                    let mut owner = None;
                    for frame in &all_loops {
                        if frame.body <= pc && pc < frame.exit { owner = Some(frame.opener); }
                    }
                    owner
                };
                let from = region(jump.at); let to = region(jump.target);
                if from != to {
                    let is_break = from.and_then(|owner| all_loops.iter().find(|f| f.opener == owner)).map(|f| f.exit == jump.target && to == f.parent).unwrap_or(false);
                    if !is_break { return load_err("LOAD_BAD_BYTECODE", format!("jump at offset {} crosses a loop boundary", jump.at)); }
                }
            }
        }
        for frame in &all_loops {
            if !starts.contains(&frame.exit) { return load_err("LOAD_BAD_BYTECODE", format!("FOR_RANGE at offset {} exits to {}, not an instruction start", frame.opener, frame.exit)); }
        }
        for (at, target) in while_exits {
            if !starts.contains(&target) || !all_loops.iter().any(|f| f.op == Op::WHILE_BEGIN && f.opener < at && f.exit == target) {
                return load_err("LOAD_BAD_BYTECODE", format!("WHILE_TEST at offset {} exits to an invalid loop region", at));
            }
        }
        for l in &self.lines { if l.pc as usize >= self.code.len() { return load_err("LOAD_BAD_BYTECODE", format!("line table entry points at pc {}, beyond the code", l.pc)); } }
        Ok(loop_pairs)
    }

    // The v5 loader computes stack depth at every reachable instruction and rejects inconsistent
    // joins and loop backedges. This is a structural fact only; it adds no run-time budget/check.
    fn verify_stack(&self, reg: &Registry) -> Result<(), Error> {
        use Op::*;
        let mut starts = Vec::new(); let mut r = Reader::new(&self.code); let mut has_loop = false;
        while !r.done() {
            starts.push(r.pos); let op = Op::decode(r.u8()?).ok_or_else(|| Error::new("LOAD_BAD_BYTECODE", "unknown opcode during stack verification"))?;
            if matches!(op, FOR_RANGE | WHILE_BEGIN) { has_loop = true; }
            match op {
                PUSH_INT => { r.i64()?; }, PUSH_FLOAT => { r.f64()?; }, PUSH_STR => { r.u32()?; }, PUSH_BOOL => { r.u8()?; },
                LOAD_LOCAL | STORE_LOCAL => { r.u16()?; }, LOAD_CTX => { r.u16()?; }, CALL_FN | CALL_METHOD => { r.u16()?; r.u8()?; },
                JUMP | JUMP_IF_FALSE | JUMP_IF_TRUE | WHILE_TEST | LOOP_BACK => { r.i32()?; },
                FOR_RANGE => { r.u16()?; r.u16()?; r.i32()?; }, FOR_NEXT => { r.u16()?; r.i32()?; }, MATH => { r.u8()?; },
                _ => {}
            }
        }
        if !has_loop { return Ok(()); }
        let mut incoming = vec![None::<i64>; starts.len()]; let mut work = vec![0usize];
        if starts.is_empty() { return load_err("LOAD_BAD_BYTECODE", "code is empty"); }
        incoming[0] = Some(0);
        let merge = |target: usize, depth: i64, starts: &[usize], incoming: &mut [Option<i64>], work: &mut Vec<usize>| -> Result<(), Error> {
            let Some(ix) = starts.iter().position(|pc| *pc == target) else { return load_err("LOAD_BAD_BYTECODE", format!("control flow targets {}, not an instruction start", target)); };
            match incoming[ix] { None => { incoming[ix] = Some(depth); work.push(ix); }, Some(old) if old != depth => return load_err("LOAD_BAD_BYTECODE", format!("inconsistent operand stack depth at control-flow join {}: {} versus {}", target, old, depth)), _ => {} }
            Ok(())
        };
        let math_arity = |fn_id: u8| -> Result<i64, Error> { Ok(match fn_id { 0..=4 | 10..=14 => 1, 5..=7 | 15..=16 => 2, 8..=9 | 17 => 3, _ => return load_err("LOAD_BAD_BYTECODE", format!("unknown MATH function {}", fn_id)) }) };
        while let Some(ix) = work.pop() {
            let pc = starts[ix]; let mut r = Reader { b: &self.code, pos: pc }; let op = Op::decode(r.u8()?).unwrap();
            let mut pop = 0i64; let mut push = 0i64; let mut targets: Vec<usize> = Vec::new(); let mut fall = true;
            match op {
                PUSH_INT | PUSH_FLOAT | PUSH_STR | PUSH_BOOL | LOAD_LOCAL | LOAD_CTX => push = 1,
                STORE_LOCAL | POP => pop = 1,
                CALL_FN => { let i = r.u16()? as usize; let argc = r.u8()? as i64; pop = argc; let returns = match &self.imports[i] { Import::Function(c) => reg.functions.get(c).map(|(_, s, _)| s.returns.as_str()), _ => None }; push = if returns == Some("void") { 0 } else { 1 }; },
                CALL_METHOD => { let i = r.u16()? as usize; let argc = r.u8()? as i64; pop = argc + 1; let returns = match &self.imports[i] { Import::Method(c, _, _) => reg.methods.get(c).map(|(_, _, s, _)| s.returns.as_str()), _ => None }; push = if returns == Some("void") { 0 } else { 1 }; },
                EQ | NE | ADD_I | SUB_I | MUL_I | DIV_I | MOD_I | ADD_F | SUB_F | MUL_F | DIV_F | LT_I | LE_I | GT_I | GE_I | LT_F | LE_F | GT_F | GE_F | CONCAT => { pop = 2; push = 1; },
                NOT | NEG_I | NEG_F | I2F | I2S | F2S | B2S => { pop = 1; push = 1; },
                MATH => { pop = math_arity(r.u8()?)?; push = 1; }, DUP => { pop = 1; push = 2; },
                JUMP => { let rel = r.i32()?; targets.push((r.pos as i64 + rel as i64) as usize); fall = false; },
                JUMP_IF_FALSE | JUMP_IF_TRUE => { let rel = r.i32()?; pop = 1; targets.push((r.pos as i64 + rel as i64) as usize); },
                FOR_RANGE => { let _ = r.u16()?; let _ = r.u16()?; let rel = r.i32()?; pop = 2; targets.push((r.pos as i64 + rel as i64) as usize); },
                FOR_NEXT => { let _ = r.u16()?; let rel = r.i32()?; targets.push((r.pos as i64 + rel as i64) as usize); },
                WHILE_BEGIN => {}, WHILE_TEST => { let rel = r.i32()?; pop = 1; targets.push((r.pos as i64 + rel as i64) as usize); },
                LOOP_BACK => { let rel = r.i32()?; targets.push((r.pos as i64 + rel as i64) as usize); fall = false; }, HALT => { fall = false; }
            }
            let depth = incoming[ix].unwrap(); if depth < pop { return load_err("LOAD_BAD_BYTECODE", format!("operand stack underflow at offset {}", pc)); }
            let after = depth - pop + push; for target in targets { merge(target, after, &starts, &mut incoming, &mut work)?; }
            if fall { if ix + 1 >= starts.len() { return load_err("LOAD_BAD_BYTECODE", "control flow falls past the end of code"); } merge(starts[ix + 1], after, &starts, &mut incoming, &mut work)?; }
        }
        Ok(())
    }

    /// Executes the chunk once against the host's objects.
    pub fn run(&self, ctx: &mut Context, reg: &Registry) -> Result<(), Error> {
        let mut stack: Vec<Value> = Vec::with_capacity(self.max_stack as usize);
        let mut locals: Vec<Value> = vec![Value::None; self.locals.len()];
        let mut r = Reader::new(&self.code);
        fn pop(stack: &mut Vec<Value>) -> Result<Value, Error> { stack.pop().ok_or_else(|| Error::new("RUN_ERROR", "stack underflow")) }
        fn push(stack: &mut Vec<Value>, v: Value) { stack.push(v); }
        fn int2(stack: &mut Vec<Value>, what: &str) -> Result<(i64, i64), Error> {
            let b = pop(stack)?; let a = pop(stack)?;
            match (&a, &b) { (Value::Int(x), Value::Int(y)) => Ok((*x, *y)), _ => err(format!("{} applied to {} and {}", what, a.kind_name(), b.kind_name())) }
        }
        fn flt2(stack: &mut Vec<Value>, what: &str) -> Result<(f64, f64), Error> {
            let b = pop(stack)?; let a = pop(stack)?;
            match (&a, &b) { (Value::Float(x), Value::Float(y)) => Ok((*x, *y)), _ => err(format!("{} applied to {} and {}", what, a.kind_name(), b.kind_name())) }
        }
        loop {
            let byte = r.u8()?;
            let op = Op::decode(byte).ok_or_else(|| Error::new("RUN_ERROR", format!("unknown opcode {}", byte)))?;
            use Op::*;
            match op {
                PUSH_INT => push(&mut stack, Value::Int(r.i64()?)),
                PUSH_FLOAT => push(&mut stack, Value::Float(r.f64()?)),
                PUSH_STR => { let s = self.consts[r.u32()? as usize].clone(); push(&mut stack, Value::Str(s)) }
                PUSH_BOOL => push(&mut stack, Value::Bool(r.u8()? != 0)),
                LOAD_LOCAL => { let s = r.u16()? as usize; if locals[s] == Value::None { return err(format!("local slot {} read before assignment", s)); } push(&mut stack, locals[s].clone()) }
                STORE_LOCAL => { let s = r.u16()? as usize; locals[s] = pop(&mut stack)?; }
                LOAD_CTX => {
                    let name = &self.contexts[r.u16()? as usize];
                    let obj = ctx.lookup(name).ok_or_else(|| Error::new("RUN_ERROR", format!("context variable '{}' was not provided by the host for this run", name)))?;
                    let type_name = reg.context_type(name).unwrap_or("").to_string();
                    push(&mut stack, Value::Obj { type_name, obj })
                }
                CALL_FN => {
                    let i = r.u16()? as usize; let argc = r.u8()? as usize;
                    let mut args = vec![Value::None; argc]; for k in (0..argc).rev() { args[k] = pop(&mut stack)?; }
                    let Import::Function(canonical) = &self.imports[i] else { return err("CALL_FN names a method import") };
                    let (_, _, f) = reg.functions.get(canonical).ok_or_else(|| Error::new("RUN_ERROR", format!("host function '{}' is not bound", canonical)))?;
                    let result = f(ctx, &args)?;
                    if result != Value::None { push(&mut stack, result); }
                }
                CALL_METHOD => {
                    let i = r.u16()? as usize; let argc = r.u8()? as usize;
                    let mut args = vec![Value::None; argc]; for k in (0..argc).rev() { args[k] = pop(&mut stack)?; }
                    let Import::Method(canonical, type_name, name) = &self.imports[i] else { return err("CALL_METHOD names a function import") };
                    let this = pop(&mut stack)?;
                    let obj = match &this {
                        Value::Obj { type_name: t, obj } if t == type_name => *obj,
                        Value::Obj { type_name: t, .. } => return err(format!("method {}.{} called on a {}", type_name, name, t)),
                        other => return err(format!("method {}.{} called on a {}", type_name, name, other.kind_name())),
                    };
                    let (_, _, _, m) = reg.methods.get(canonical).ok_or_else(|| Error::new("RUN_ERROR", format!("method '{}.{}' is not bound", type_name, name)))?;
                    let result = m(ctx, obj, &args)?;
                    if result != Value::None { push(&mut stack, result); }
                }
                EQ | NE => {
                    let b = pop(&mut stack)?; let a = pop(&mut stack)?;
                    let eq = match (&a, &b) {
                        (Value::Int(x), Value::Int(y)) => x == y, (Value::Float(x), Value::Float(y)) => x == y, (Value::Str(x), Value::Str(y)) => x == y,
                        (Value::Bool(x), Value::Bool(y)) => x == y, (Value::Obj { obj: x, .. }, Value::Obj { obj: y, .. }) => x == y,
                        _ => return err(format!("cannot compare {} with {}", a.kind_name(), b.kind_name())),
                    };
                    push(&mut stack, Value::Bool(if op == EQ { eq } else { !eq }))
                }
                ADD_I | SUB_I | MUL_I | DIV_I | MOD_I => {  // 64-bit two's complement, wrapping (R34: no overflow trap)
                    let (x, y) = int2(&mut stack, "int operator")?;
                    let v = match op {
                        ADD_I => x.wrapping_add(y), SUB_I => x.wrapping_sub(y), MUL_I => x.wrapping_mul(y),
                        DIV_I => { if y == 0 { return err("int division by zero"); } x.wrapping_div(y) }
                        _ => { if y == 0 { return err("int modulo by zero"); } x.wrapping_rem(y) }
                    };
                    push(&mut stack, Value::Int(v))
                }
                LT_I | LE_I | GT_I | GE_I => { let (x, y) = int2(&mut stack, "int operator")?; push(&mut stack, Value::Bool(match op { LT_I => x < y, LE_I => x <= y, GT_I => x > y, _ => x >= y })) }
                ADD_F | SUB_F | MUL_F | DIV_F => { let (x, y) = flt2(&mut stack, "float operator")?; push(&mut stack, Value::Float(match op { ADD_F => x + y, SUB_F => x - y, MUL_F => x * y, _ => x / y })) }
                LT_F | LE_F | GT_F | GE_F => { let (x, y) = flt2(&mut stack, "float operator")?; push(&mut stack, Value::Bool(match op { LT_F => x < y, LE_F => x <= y, GT_F => x > y, _ => x >= y })) }
                NEG_I => { let a = pop(&mut stack)?; match a { Value::Int(i) => push(&mut stack, Value::Int(i.wrapping_neg())), o => return err(format!("int negation applied to {}", o.kind_name())) } }
                NEG_F => { let a = pop(&mut stack)?; match a { Value::Float(f) => push(&mut stack, Value::Float(-f)), o => return err(format!("float negation applied to {}", o.kind_name())) } }
                I2F => { let a = pop(&mut stack)?; match a { Value::Int(i) => push(&mut stack, Value::Float(i as f64)), o => return err(format!("float() applied to {}", o.kind_name())) } }
                MATH => {
                    let fn_id = r.u8()?;
                    fn math_min(a: f64, b: f64) -> f64 { if a.is_nan() || b.is_nan() { f64::NAN } else if a <= b { a } else { b } }
                    fn math_max(a: f64, b: f64) -> f64 { if a.is_nan() || b.is_nan() { f64::NAN } else if a >= b { a } else { b } }
                    match fn_id {
                        0..=4 | 10..=12 => {
                            let a = pop(&mut stack)?;
                            let Value::Float(x) = a else { unreachable!("verified float math operand") };
                            let v = match fn_id {
                                0 => x.sin(), 1 => x.cos(), 2 => x.sqrt(), 3 => x.abs(), 4 => x.floor(),
                                10 => { let t = math_min(math_max(x, 0.0), 1.0); let t2 = t * t; let slope = 3.0 - 2.0 * t; t2 * slope },
                                11 => { let t = math_min(math_max(x, 0.0), 1.0); t * t },
                                12 => { let t = math_min(math_max(x, 0.0), 1.0); let d = 1.0 - t; let d2 = d * d; 1.0 - d2 },
                                _ => unreachable!(),
                            };
                            push(&mut stack, Value::Float(v));
                        }
                        13 => { let a = pop(&mut stack)?; let Value::Float(x) = a else { unreachable!("verified float math operand") }; push(&mut stack, Value::Int(x as i64)); }
                        14 => { let a = pop(&mut stack)?; let Value::Int(x) = a else { unreachable!("verified integer math operand") }; push(&mut stack, Value::Int(x.wrapping_abs())); }
                        5 | 6 | 7 | 15 | 16 => {
                            let b = pop(&mut stack)?; let a = pop(&mut stack)?;
                            match (fn_id, a, b) {
                                (5, Value::Float(x), Value::Float(y)) => push(&mut stack, Value::Float(x.powf(y))),
                                (6, Value::Float(x), Value::Float(y)) => push(&mut stack, Value::Float(math_min(x, y))),
                                (7, Value::Float(x), Value::Float(y)) => push(&mut stack, Value::Float(math_max(x, y))),
                                (15, Value::Int(x), Value::Int(y)) => push(&mut stack, Value::Int(x.min(y))),
                                (16, Value::Int(x), Value::Int(y)) => push(&mut stack, Value::Int(x.max(y))),
                                _ => unreachable!("verified math operands"),
                            }
                        }
                        8 | 9 | 17 => {
                            let hi = pop(&mut stack)?; let lo = pop(&mut stack)?; let x = pop(&mut stack)?;
                            match (fn_id, x, lo, hi) {
                                (8, Value::Float(x), Value::Float(lo), Value::Float(hi)) => push(&mut stack, Value::Float(math_min(math_max(x, lo), hi))),
                                (9, Value::Float(a), Value::Float(b), Value::Float(t)) => { let delta = b - a; let scaled = delta * t; push(&mut stack, Value::Float(a + scaled)); },
                                (17, Value::Int(x), Value::Int(lo), Value::Int(hi)) => push(&mut stack, Value::Int(x.max(lo).min(hi))),
                                _ => unreachable!("verified math operands"),
                            }
                        }
                        _ => unreachable!("verified math function"),
                    }
                }
                NOT => { let a = pop(&mut stack)?; match a { Value::Bool(b) => push(&mut stack, Value::Bool(!b)), o => return err(format!("! applied to a {}", o.kind_name())) } }
                JUMP => { let rel = r.i32()?; jump(&mut r, rel)?; }
                JUMP_IF_FALSE | JUMP_IF_TRUE => {
                    let rel = r.i32()?; let c = pop(&mut stack)?;
                    match c { Value::Bool(b) => { if b == (op == JUMP_IF_TRUE) { jump(&mut r, rel)?; } } o => return err(format!("condition is a {}, not a bool", o.kind_name())) }
                }
                FOR_RANGE => {
                    let counter = r.u16()? as usize;
                    let end = r.u16()? as usize;
                    let rel = r.i32()?;
                    let end_value = pop(&mut stack)?;
                    let start_value = pop(&mut stack)?;
                    let (Value::Int(start), Value::Int(end_value)) = (start_value, end_value) else {
                        unreachable!("compiler guarantees integer range bounds")
                    };
                    locals[counter] = Value::Int(start);
                    locals[end] = Value::Int(end_value);
                    if start >= end_value { jump(&mut r, rel)?; }
                }
                FOR_NEXT => {
                    let encoded_end = r.u16()? as usize;
                    let rel = r.i32()?;
                    let (counter, end) = self.loop_pairs.get(&(r.pos - 7)).copied().expect("verified FOR_NEXT metadata");
                    let _ = encoded_end;
                    locals[counter] = match locals[counter] {
                        Value::Int(i) => Value::Int(i.wrapping_add(1)),
                        _ => unreachable!("verified range counter local is an int"),
                    };
                    let current = match (&locals[counter], &locals[end]) {
                        (Value::Int(i), Value::Int(limit)) => (*i, *limit),
                        _ => unreachable!("verified range locals are ints"),
                    };
                    if current.0 < current.1 { jump(&mut r, rel)?; }
                }
                WHILE_BEGIN => {}
                WHILE_TEST => {
                    let rel = r.i32()?; let condition = pop(&mut stack)?;
                    let Value::Bool(b) = condition else { unreachable!("verified while condition is bool") };
                    if !b { jump(&mut r, rel)?; }
                }
                LOOP_BACK => { let rel = r.i32()?; jump(&mut r, rel)?; }
                DUP => { let top = stack.last().cloned().ok_or_else(|| Error::new("RUN_ERROR", "stack underflow"))?; push(&mut stack, top) }
                POP => { pop(&mut stack)?; }
                HALT => return Ok(()),
                CONCAT => {
                    let b = pop(&mut stack)?; let a = pop(&mut stack)?;
                    match (a, b) {
                        (Value::Str(mut x), Value::Str(y)) => { x.push_str(&y); push(&mut stack, Value::Str(x)) }
                        (a, b) => return err(format!("string + applied to {} and {}", a.kind_name(), b.kind_name())),
                    }
                }
                I2S => { let a = pop(&mut stack)?; match a { Value::Int(i) => push(&mut stack, Value::Str(i.to_string())), o => return err(format!("str(int) applied to {}", o.kind_name())) } }
                F2S => { let a = pop(&mut stack)?; match a { Value::Float(f) => push(&mut stack, Value::Str(format_g15(f))), o => return err(format!("str(float) applied to {}", o.kind_name())) } }
                B2S => { let a = pop(&mut stack)?; match a { Value::Bool(b) => push(&mut stack, Value::Str(if b { "true".into() } else { "false".into() })), o => return err(format!("str(bool) applied to {}", o.kind_name())) } }
            }
        }
    }
}

fn jump(r: &mut Reader<'_>, rel: i32) -> Result<(), Error> {
    let target = r.pos as i64 + rel as i64;
    if target < 0 { return err("jump before the code start"); }
    if target as usize > r.b.len() { return err(format!("jump target {} is outside the code", target)); }
    r.pos = target as usize; Ok(())
}

/// The text of `str(float)`: C's `%.15g`, which the C++ runtime and every conformance vector use.
pub fn format_g15(x: f64) -> String {
    if x.is_nan() { return "nan".into(); }
    if x.is_infinite() { return if x > 0.0 { "inf".into() } else { "-inf".into() }; }
    if x == 0.0 { return if x.is_sign_negative() { "-0".into() } else { "0".into() }; }
    let sci = format!("{:.14e}", x);                       // d.dddddddddddddde±X with 15 significant digits
    let (mant, exp) = sci.split_once('e').unwrap();
    let exp: i32 = exp.parse().unwrap();
    let trim = |s: &str| -> String { let s = if s.contains('.') { s.trim_end_matches('0').trim_end_matches('.') } else { s }; s.to_string() };
    if exp < -4 || exp >= 15 {
        format!("{}e{}{:02}", trim(mant), if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        let decimals = (14 - exp).max(0) as usize;
        trim(&format!("{:.*}", decimals, x))
    }
}

#[cfg(test)]
mod format_tests {
    use super::format_g15;
    #[test]
    fn matches_c_printf_g15() {
        for (x, want) in [(0.1 + 0.2, "0.3"), (1.0, "1"), (123456789.125, "123456789.125"), (1.0 / 3.0, "0.333333333333333"), (-0.0, "-0"), (f64::INFINITY, "inf"),
            (2.5, "2.5"), (-0.5, "-0.5"), (1e21, "1e+21"), (1.5e-7, "1.5e-07"), (123456789012345680.0, "1.23456789012346e+17"), (0.0001, "0.0001"), (0.00001, "1e-05"), (6.32455532033676, "6.32455532033676")] {
            assert_eq!(format_g15(x), want, "{}", x);
        }
    }
}
